<script setup lang="ts">
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {marked} from 'marked';import DOMPurify from 'dompurify';
import ShareSettings from './ShareSettings.vue';
import PrototypePreview from './PrototypePreview.vue';
import {api,labels,when,download} from './api';import Icon from './Icon.vue';
const props=defineProps<{projectId:string;userId:string;project:any;items:any[];models:any[];canEdit:boolean;messages:any[]}>();const emit=defineEmits(['refresh','edit','settings','notify']);const route=useRoute(),router=useRouter();
const initialModel=props.models.find(m=>m.base_url==='codex://local')||props.models[0];
const kind=ref(String(route.query.type||'prd')),target=ref(String(route.query.target||'')),model=ref(initialModel?.id||''),language=ref('vue'),surface=ref('frontend'),multiAgent=ref(false),prompt=ref(''),busy=ref(false),error=ref(''),result=ref<any>(null),previewHtml=ref(''),frame=ref<HTMLIFrameElement>(),conversation=ref<HTMLElement>(),input=ref<HTMLTextAreaElement>(),started=ref(0),seconds=ref(0),pendingPrompt=ref(''),outputTab=ref('preview');
const showShare=ref(false);
watch(()=>result.value?.id,()=>showShare.value=false);
const requestId=ref(''),pausing=ref(false),paused=ref(false);
function newRequestId(){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;}
async function pause(){if(!busy.value||pausing.value)return;pausing.value=true;try{await api(`/projects/${props.projectId}/generate/${requestId.value}/pause`,'POST',{});}catch(e:any){if(busy.value)error.value=e.message;}finally{pausing.value=false;}}
const draftKey='pm-studio-draft-'+props.userId+'-'+props.projectId;
try{prompt.value=sessionStorage.getItem(draftKey)||'';}catch{}
watch(prompt,v=>{try{v?sessionStorage.setItem(draftKey,v):sessionStorage.removeItem(draftKey);}catch{}});
const modes=[{id:'prd',name:'产品需求文档',short:'PRD',icon:'FileText',description:'从目标、流程到验收标准'},{id:'prototype',name:'交互原型',short:'原型',icon:'PanelsTopLeft',description:'把需求变成可演示的界面'},{id:'technical',name:'技术交付文档',short:'技术文档',icon:'Code2',description:'架构、接口、字段与实现约束'},{id:'note',name:'产品笔记',short:'笔记',icon:'ListTodo',description:'沉淀讨论结论与待办事项'},{id:'chat',name:'产品讨论',short:'讨论',icon:'MessageSquare',description:'澄清问题，寻找下一步方向'}];
const mode=computed(()=>modes.find(m=>m.id===kind.value)||modes[0]);const context=computed(()=>props.items.find(i=>i.id===target.value));const history=computed(()=>props.messages.filter(m=>(m.item_id||'')===target.value));const deliverables=computed(()=>props.items.filter(i=>(kind.value==='chat'?['document','prototype'].includes(i.kind):kind.value==='prototype'?i.kind==='prototype':i.kind==='document'&&i.body.type===kind.value)&&(!target.value||i.id===target.value||i.body.requirementId===target.value)));const rendered=computed(()=>markdown(result.value?.body.content||''));const canSend=computed(()=>props.canEdit&&props.projectId&&model.value&&prompt.value.trim()&&!busy.value);
function modelLabel(m:any){return m.base_url==='codex://local'?`Codex · 服务器本机（${m.model}）`:`${m.name}（${m.model}）`;}
watch([kind,target],()=>{result.value=null;previewHtml.value='';error.value='';});
function markdown(s:string){return DOMPurify.sanitize(marked.parse(s) as string);}
function choose(id:string){if(busy.value)return;kind.value=id;router.replace({path:'/studio',query:{...route.query,type:id}});input.value?.focus();}
function changeContext(){result.value=null;router.replace({path:'/studio',query:{...route.query,target:target.value||undefined}});}
function suggestion(){const name=context.value?.title||props.project?.name||'这个产品';const text:any={prd:`请基于「${name}」的现有需求，生成完整 PRD。明确用户目标、业务流程、功能规则、边界情况和可验证的验收标准；缺失的信息标注待确认。`,prototype:`请为「${name}」设计可交互原型。参考项目需求，明确页面结构、核心操作、空状态与异常提示，使用真实数据接口。`,technical:`请为「${name}」编写研发交付文档，包含架构、接口请求与响应、MySQL 字段、校验规则、权限和异常处理。`,note:`请整理「${name}」的产品笔记，归纳现有需求、已知约束、关键决策和待确认问题。`,chat:`请评审「${name}」的需求完整性，指出关键用户路径中的遗漏和待确认问题。`};prompt.value=text[kind.value];input.value?.focus();}
async function selectResult(i:any){result.value=i;previewHtml.value='';outputTab.value='preview';}
async function send(){if(!canSend.value)return;busy.value=true;paused.value=false;requestId.value=newRequestId();seconds.value=0;error.value='';started.value=Date.now();pendingPrompt.value=prompt.value;const project=props.projectId;try{const r=await api(`/projects/${project}/generate`,'POST',{requestId:requestId.value,modelId:model.value,prompt:prompt.value,kind:kind.value,itemId:target.value||undefined,language:language.value,surface:surface.value,multiAgent:multiAgent.value});if(r.paused){paused.value=true;emit('refresh');return;}prompt.value='';emit('refresh');if(r.item){await selectResult(r.item);emit('notify','创作成果已保存，可继续提出修改意见');}else emit('notify','讨论已保存到项目');}catch(e:any){error.value=e.message;emit('refresh');}finally{busy.value=false;pendingPrompt.value='';await scroll();}}
async function scroll(){await nextTick();conversation.value?.scrollTo({top:conversation.value.scrollHeight,behavior:'smooth'});}
function continueResult(){target.value=result.value.id;kind.value=result.value.kind==='prototype'?'prototype':result.value.body.type;changeContext();input.value?.focus();}
function keydown(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();send();}}
watch(()=>context.value?.id,()=>{if(context.value?.kind==='prototype'){language.value=context.value.body.language;surface.value=context.value.body.surface;}},{immediate:true});
watch(()=>props.items,()=>{if(result.value){const latest=props.items.find(i=>i.id===result.value.id);if(latest&&latest.version!==result.value.version)selectResult(latest);}});
watch(()=>props.models.map(m=>m.id),()=>{if(!props.models.some(m=>m.id===model.value))model.value=(props.models.find(m=>m.base_url==='codex://local')||props.models[0])?.id||'';},{deep:true});watch(()=>props.projectId,()=>{target.value='';result.value=null;error.value='';});watch(()=>props.messages.length,scroll);watch(()=>route.query.target,v=>{target.value=String(v||'');});watch(()=>route.query.type,v=>{kind.value=modes.some(m=>m.id===v)?String(v):'prd';});
let timer:any,poll:any;onMounted(()=>{timer=setInterval(()=>{if(busy.value)seconds.value=Math.floor((Date.now()-started.value)/1000);},1000);poll=setInterval(()=>{if(busy.value)emit('refresh');},7000);scroll();});onUnmounted(()=>{clearInterval(timer);clearInterval(poll);removeGuard();});const removeGuard=router.beforeEach((to,from)=>{if(to.path===from.path)return;if(busy.value)return confirm('AI 仍在生成，离开后结果会保存到项目。确定离开吗？');});
</script>
<template><section class="studio-page"><div class="studio-heading"><div><span class="eyebrow">THINK · CREATE · ITERATE</span><h1>AI 创作中心 <span>把想法推进到交付</span></h1><p>带着项目上下文，一起完成需求、文档与原型。</p></div><span class="badge"><Icon name="FolderKanban" :size="14"/>{{project?.name||'先创建一个产品项目'}}</span></div><div v-if="error" class="error-banner" role="alert"><Icon name="AlertCircle"/><span>{{error}}<small v-if="prompt">你的输入已保留，可以调整后重试。</small></span><button class="icon-button" @click="error=''" title="关闭错误"><Icon name="X"/></button></div>
<div class="studio-layout"><aside class="studio-context"><div class="studio-section-label">这次想完成什么</div><button v-for="m in modes" :key="m.id" class="creation-mode" :class="{selected:kind===m.id}" :disabled="busy" @click="choose(m.id)"><Icon :name="m.icon" :size="21"/><span><strong>{{m.name}}</strong><small>{{m.description}}</small></span><Icon name="ChevronRight" :size="14"/></button><div class="studio-context-fields"><label>关联需求或已有成果<select v-model="target" :disabled="busy" @change="changeContext"><option value="">使用整个项目上下文</option><option v-for="i in items.filter(i=>['requirement','document','prototype'].includes(i.kind))" :value="i.id">{{i.title}}</option></select></label><div class="context-summary"><Icon name="Database" :size="15"/><p v-if="context">已关联「{{context.title}}」，对话与修改记录保留在此内容下。</p><p v-else>使用本项目的 {{items.filter(i=>i.kind==='requirement').length}} 条需求作为创作参考。</p></div><template v-if="kind==='prototype'"><label>原型开发语言<select v-model="language" :disabled="busy"><option value="vue">Vue</option><option value="html">HTML / JavaScript</option><option value="react">React</option></select></label><label>原型端<select v-model="surface" :disabled="busy"><option value="frontend">前台用户界面</option><option value="admin">后台管理界面</option></select></label></template><label class="check-label"><input type="checkbox" v-model="multiAgent" :disabled="busy"/>多 Agent 协作</label><p class="muted">需求分析 → 技术评审 → 内容交付</p></div></aside>
<section class="studio-conversation"><header><div class="inline"><span class="mini-spark"><Icon name="Sparkles"/></span><div><h3>{{mode.name}}创作</h3><small>{{busy?'正在生成，可在这里查看进展':'描述目标，逐步完善每个细节'}}</small></div></div><select v-model="model" :disabled="busy" aria-label="创作模型"><option value="">{{models.length?'选择模型':'尚未配置模型'}}</option><option v-for="m in models" :key="m.id" :value="m.id">{{modelLabel(m)}}</option></select></header>
<div ref="conversation" class="studio-messages"><div v-if="!history.length&&!busy" class="studio-welcome"><div class="studio-emblem"><Icon :name="mode.icon" :size="32"/></div><h2>从一句需求，到一份清晰的{{mode.short}}</h2><p>{{mode.description}}。你可以直接描述想法，<br>也可以关联已有需求，继续打磨。</p><button class="prompt-suggestion" @click="suggestion"><Icon name="Sparkles" :size="17"/><span>根据现有项目，帮我{{kind==='prototype'?'设计交互原型':kind==='chat'?'梳理需求问题':'编写'+mode.short}}</span><Icon name="ArrowUpRight" :size="15"/></button><div class="creation-steps"><span>01 选择创作内容</span><Icon name="ChevronRight" :size="12"/><span>02 描述你的目标</span><Icon name="ChevronRight" :size="12"/><span>03 审阅并迭代</span></div></div><article v-for="m in history" :key="m.id" class="studio-message" :class="m.role"><div class="message-author"><span class="avatar tiny"><Icon v-if="m.role==='assistant'" name="Sparkles" :size="12"/><template v-else>{{(m.name||'我').slice(0,1)}}</template></span><strong>{{m.role==='user'?m.name:m.agent||'产品助手'}}</strong><small>{{when(m.created_at)}}</small><span class="badge" v-if="['failed','paused'].includes(m.status)">{{m.status==='paused'?'已暂停':'未完成'}}</span></div><div v-if="m.role==='user'" class="message-text">{{m.content}}</div><details v-else-if="m.content.includes('<template>')||m.content.includes('<!DOCTYPE')||m.content.includes('<!doctype')"><summary>查看生成的原型源码</summary><pre>{{m.content}}</pre></details><div v-else class="markdown-body" v-html="markdown(m.content)"></div><button v-if="['failed','paused'].includes(m.status)&&!busy" class="text-button accent" @click="prompt=m.content;input?.focus()">载入指令重试</button></article><div v-if="busy" class="studio-working"><Icon name="LoaderCircle" class="spin"/><div><strong>{{multiAgent?'多个 Agent 正在分析与创作':'正在结合项目需求生成'+mode.short}}</strong><p>{{seconds}} 秒 · 结果将自动保存到项目</p></div></div></div>
<div v-if="!models.length" class="studio-model-notice"><Icon name="AlertCircle" :size="17"/><span>先连接一个 AI 模型，即可开始真实创作。</span><button @click="emit('settings')">配置模型<Icon name="ArrowUpRight" :size="14"/></button></div><div v-else-if="!canEdit" class="studio-model-notice">当前项目为只读权限，编辑成员可以发起创作。</div><p v-if="paused" class="studio-paused" role="status">已暂停，输入和已完成内容已保留。再次创作将重新发起生成。</p><form class="studio-composer" @submit.prevent="send"><textarea ref="input" v-model="prompt" rows="4" maxlength="20000" :disabled="busy" @keydown="keydown" :placeholder="'描述你想要的'+mode.name+'，包括目标用户、关键流程和特别要求…'" aria-label="创作指令"/><footer><span><Icon name="Link" :size="13"/>{{context?'已关联内容':'项目上下文已就绪'}}</span><small>{{prompt.length}} / 20000 · 草稿已暂存</small><button v-if="busy" type="button" class="secondary" :disabled="pausing" @click="pause"><Icon :name="pausing?'LoaderCircle':'Pause'" :class="{spin:pausing}" :size="16"/>{{pausing?'正在暂停':'暂停创作'}}</button><button v-else class="primary" :disabled="!canSend"><Icon :name="busy?'LoaderCircle':'Sparkles'" :class="{spin:busy}" :size="16"/>{{paused?'重新创作':'开始创作'}}</button></footer></form></section>
<aside class="studio-output"><header><div><h3>{{kind==='chat'?'讨论参考资料':mode.name+'成果'}}</h3><small>{{kind==='chat'?'查看已有文档与原型，辅助讨论':'仅显示当前类型，保存到项目后可继续迭代'}}</small></div><span class="badge">{{deliverables.length}}</span></header><template v-if="result"><div class="output-title"><span class="badge">{{result.kind==='prototype'?'交互原型':labels[result.body.type]}} · v{{result.version}}</span><h3>{{result.title}}</h3><div class="inline"><button class="text-button accent" @click="emit('edit',result)"><Icon name="Code2" :size="13"/>编辑</button><button class="text-button" @click="download(result)"><Icon name="Download" :size="13"/>下载</button><button v-if="project?.role==='owner'" class="text-button" @click="showShare=!showShare"><Icon name="Share2" :size="13"/>对外分享</button><button class="text-button" @click="result=null">返回列表</button></div></div><ShareSettings v-if="showShare" :item-id="result.id"/><div v-if="result.kind==='document'" class="markdown-body output-preview" v-html="rendered"></div><PrototypePreview v-else :key="result.id" :item="result"/><button class="secondary continue-output" @click="continueResult"><Icon name="MessageSquare" :size="15"/>基于这个成果继续修改</button></template><template v-else><div v-if="!deliverables.length" class="output-empty"><Icon :name="mode.icon" :size="35"/><h4>{{kind==='chat'?'暂无可参考的文档或原型':'暂无'+mode.name+'成果'}}</h4><p>{{kind==='chat'?'讨论记录保留在中间对话区。':'生成的'+mode.name+'会自动保存并展示在这里。'}}</p></div><button v-for="i in deliverables" :key="i.id" class="output-card" @click="selectResult(i)"><span class="project-icon small"><Icon :name="i.kind==='prototype'?'PanelsTopLeft':'FileText'" :size="17"/></span><div><strong>{{i.title}}</strong><small>{{i.kind==='prototype'?'交互原型':labels[i.body.type]}} · v{{i.version}} · {{when(i.updated_at)}}</small></div><Icon name="ChevronRight" :size="14"/></button></template></aside></div></section></template>
